INSERT INTO retry_feedback_templates (template_code, template_type, payload)
VALUES ('partial-answer-needs-refinement', 'explanation', '{"title":"Вы смотрите в правильную область, но команду ещё нужно уточнить","tone":"partial","messageTemplate":"`{{submittedAnswer}}` указывает на правильный сигнал репозитория, но задаче всё ещё нужна более точная команда проверки, прежде чем ответ станет правильным.","details":["Пользователь уже стартовал из правильного семейства команд проверки, поэтому сообщение о повторе должно поддержать это направление, а не считать ответ полным промахом.","Следующая подсказка может сузить форму команды, не меняя саму панель обратной связи."]}'::jsonb);

INSERT INTO retry_feedback_templates (template_code, template_type, payload)
VALUES ('unsupported-answer-type', 'explanation', '{"title":"Вернитесь к поддерживаемому вводу команды","tone":"unsupported","messageTemplate":"Сейчас проверяются только ответы в виде команды, поэтому перед следующей попыткой нужно вернуть поддерживаемый формат.","details":["Запрос принимается, но такой тип ответа всё ещё считается неподдерживаемым.","Панель повтора должна сначала вернуть пользователя к поддерживаемому командному формату, а уже потом пробовать более богатые варианты ответа."]}'::jsonb)
ON CONFLICT (template_code) DO NOTHING;

INSERT INTO retry_feedback_templates (template_code, template_type, payload)
VALUES ('branch-choice-needs-task-alignment', 'explanation', '{"title":"Подтвердите текущую ветку до решения о переключении","tone":"incorrect","messageTemplate":"В этом сценарии безопасный следующий шаг — сначала прочитать активную ветку или branch-aware status, потому что репозиторий уже содержит незавершённые hotfix-изменения. Переключение прямо сейчас оставалось бы догадкой.","details":["Сценарий пока не просит выполнять `checkout`. Сначала он требует собрать минимальный branch cue и подтвердить, где уже открыта работа.","После такой проверки пользователь сможет аргументированно решить, допустимо ли переключение, не смешивая hotfix и feature-контекст."]}'::jsonb)
ON CONFLICT (template_code) DO NOTHING;

INSERT INTO retry_feedback_templates (template_code, template_type, payload)
VALUES ('history-cleanup-requires-plan-first', 'explanation', '{"title":"Сначала просмотрите историю, потом переписывайте коммиты","tone":"incorrect","messageTemplate":"В этом сценарии следующий безопасный шаг — сначала показать недавний стек истории в читаемом виде, потому что `fixup!` и WIP-сигналы ещё нужно явно увидеть до любого `rebase`.","details":["Правильная следующая попытка остаётся в семействе `git log` и помогает увидеть, какие коммиты вообще войдут в cleanup.","Только после такого preview можно аргументированно обсуждать interactive rebase или другую команду переписывания."]}'::jsonb)
ON CONFLICT (template_code) DO NOTHING;

INSERT INTO retry_feedback_templates (template_code, template_type, payload)
VALUES ('inspection-command-should-come-before-mutation', 'explanation', '{"title":"Проверьте рабочее дерево до любых изменений","tone":"incorrect","messageTemplate":"Безопасное следующее действие в этом сценарии — сначала проверить состояние репозитория, а не сразу переходить к изменяющей команде.","details":["Это упражнение про чтение текущего состояния до действия, а не про выбор целевой ветки или изменение файлов.","Панель повтора должна удерживать пользователя в цикле проверки, пока форма правильной команды не станет очевидной."]}'::jsonb)
ON CONFLICT (template_code) DO NOTHING;

INSERT INTO retry_feedback_templates (template_code, template_type, payload)
VALUES ('remote-sync-requires-fetch-first', 'explanation', '{"title":"Сначала обновите удалённое состояние, потом интегрируйте","tone":"incorrect","messageTemplate":"В этом сценарии безопасный следующий шаг — отдельно получить новые remote refs, потому что без свежего `fetch` решение о `pull` или другой интеграции остаётся преждевременным.","details":["Правильная следующая попытка должна оставаться в семействе `git fetch` и обновить наблюдаемое состояние `origin/main` без слияния.","Только после такого preview можно предметно решать, нужен ли `pull`, `merge` или `rebase`."]}'::jsonb)
ON CONFLICT (template_code) DO NOTHING;

INSERT INTO retry_feedback_templates (template_code, template_type, payload)
VALUES ('retry-guidance-needs-scenario-review', 'explanation', '{"title":"Вернитесь к цели сценария перед следующей попыткой","tone":"incorrect","messageTemplate":"Цикл повтора должен вернуть пользователя к цели сценария, а затем сузить следующую попытку самым маленьким доступным безопасным намёком.","details":["Когда сценарно-специфичная подсказка недоступна, объяснение должно оставаться сфокусированным на цели задачи, а не изобретать новые правила.","Следующая подсказка всё ещё может сузить путь повтора, не затрагивая слой policy."]}'::jsonb)
ON CONFLICT (template_code) DO NOTHING;

INSERT INTO retry_feedback_templates (template_code, template_type, payload)
VALUES ('partial-answer', 'hint', '{"nudgeTitle":"Останьтесь в том же семействе проверок","nudgeMessage":"Оставайтесь в той же зоне проверки, но уберите лишний охват или переключитесь на каноничную безопасную команду для сценария.","strongTitle":"Сверьтесь с точным безопасным шагом","strongMessage":"Ищите самую маленькую команду, которая проверяет именно то состояние репозитория, о котором спрашивает задача, без лишнего намерения."}'::jsonb)
ON CONFLICT (template_code) DO NOTHING;

INSERT INTO retry_feedback_templates (template_code, template_type, payload)
VALUES ('unsupported-answer-type', 'hint', '{"nudgeTitle":"Используйте режим текста команды","nudgeMessage":"Переключите тип ответа обратно на текст команды и оставьте следующую попытку в форме простой команды проверки.","strongTitle":"Ориентируйтесь на поддерживаемый пример","strongMessage":"Посмотрите на бейдж поддерживаемого типа ответа над формой и сначала вернитесь к этому режиму."}'::jsonb)
ON CONFLICT (template_code) DO NOTHING;

INSERT INTO retry_feedback_templates (template_code, template_type, payload)
VALUES ('branch-intent', 'hint', '{"nudgeTitle":"Сначала подтвердите активную ветку","nudgeMessage":"Выберите branch-reading шаг, который ничего не меняет в репозитории, но явно показывает, где сейчас открыта работа.","strongTitle":"Выберите команду чтения branch-контекста","strongMessage":"Нужна самая маленькая команда из семейства `git branch --show-current` или branch-aware `git status`, которая подтверждает текущую ветку до любых решений о `checkout`."}'::jsonb)
ON CONFLICT (template_code) DO NOTHING;

INSERT INTO retry_feedback_templates (template_code, template_type, payload)
VALUES ('history-plan', 'hint', '{"nudgeTitle":"Сначала покажите компактную историю","nudgeMessage":"Оставайтесь в preview-режиме и выберите команду, которая показывает верхушку истории с `fixup!` и WIP, не меняя коммиты.","strongTitle":"Выберите команду просмотра графа истории","strongMessage":"Нужна компактная команда из семейства `git log --oneline --decorate`; вариант с `--graph` тоже подходит, если делает стек читаемее."}'::jsonb)
ON CONFLICT (template_code) DO NOTHING;

INSERT INTO retry_feedback_templates (template_code, template_type, payload)
VALUES ('working-tree-inspection', 'hint', '{"nudgeTitle":"Начните с проверки рабочего дерева","nudgeMessage":"Сценарий спрашивает о состоянии репозитория, поэтому следующая попытка должна оставаться в семействе `git status`, а не менять файлы или ветки.","strongTitle":"Используйте `git status` как безопасный первый шаг","strongMessage":"Сначала отправьте `git status` или `git status --short`, чтобы подтвердить изменённые и неотслеживаемые файлы до любого следующего действия."}'::jsonb)
ON CONFLICT (template_code) DO NOTHING;

INSERT INTO retry_feedback_templates (template_code, template_type, payload)
VALUES ('remote-fetch', 'hint', '{"nudgeTitle":"Сначала получите свежие remote refs","nudgeMessage":"Выберите отдельный шаг получения данных с удалённого репозитория, который обновляет картину `origin/main`, но не интегрирует изменения в локальную ветку.","strongTitle":"Выберите команду из семейства `git fetch`","strongMessage":"Нужна команда вроде `git fetch` или `git fetch origin`, а не `pull`, потому что сценарий сначала оценивает обновление remote-tracking состояния."}'::jsonb)
ON CONFLICT (template_code) DO NOTHING;

INSERT INTO retry_feedback_templates (template_code, template_type, payload)
VALUES ('generic-retry', 'hint', '{"nudgeTitle":"Вернитесь к цели сценария","nudgeMessage":"Переформулируйте задачу в одном предложении и держите следующую попытку сфокусированной на самой маленькой безопасной команде, которая на неё отвечает.","strongTitle":"Покажите самый маленький безопасный следующий шаг","strongMessage":"Уберите лишнее намерение и выберите команду, которая даёт недостающий сигнал до любого более крупного действия."}'::jsonb)
ON CONFLICT (template_code) DO NOTHING;
